function save(){write('db',db)}function record(action){db.logs.unshift({time:now(),user:user?.name||'',action});save()}
function modal(title,body,footer=''){ $('#modal-body').innerHTML=`<div class="modal-content"><div class="modal-head"><h2>${title}</h2><button class="btn link" onclick="closeModal()">关闭</button></div>${body}<div class="modal-actions">${footer}</div></div>`;$('#modal').showModal() }function closeModal(){$('#modal').close()}function go(p,t=''){if((p==='qa-edit'||p==='qa-settings')&&current?.status==='已发布')return;page=p;tab=t;render()}function opts(arr,val){return arr.map(x=>`<option value="${esc(x.id)}" ${x.id===val?'selected':''}>${esc(x.name)}</option>`).join('')}function selection(type,val){return '<option value="">请选择</option>'+opts(db.resources.filter(x=>x.type===type&&x.status==='可用'),val)}
function nextDisplayName(){const used=new Set([...db.members.map(m=>m.displayName||m.name||''),...Object.values(db.accountProfiles||{}).map(p=>p.displayName||'')]);let n=1;while(used.has('用户'+String(n).padStart(3,'0')))n++;return '用户'+String(n).padStart(3,'0')}
function login(){let role=$('#role').value,accountName=$('#username').value.trim(),pw=$('#password').value;if(!accountName||!pw){$('#loginError').textContent='请输入账号和密码';return}let member=db.members.find(m=>m.username===accountName);db.accountProfiles=db.accountProfiles||{};let profile=db.accountProfiles[accountName]||{};let displayName=member?.displayName||member?.name||profile.displayName||nextDisplayName();if(member&&!member.displayName)member.displayName=displayName;if(!member)db.accountProfiles[accountName]={...profile,displayName};save();user={account:accountName,memberId:member?.id||null,name:displayName,role};write('user',user);go('broadcast')}
function render(){if(!user){$('#app').innerHTML=`<main class="demo-welcome"><img src="brand.svg?v=2" alt="澄屿数字"><p>澄屿数字 / 工作空间</p><h1>让想法，拥有表达。</h1><p class="muted">选择一个角色，开始体验内容制作与团队协作。</p><div class="welcome-roles">${['普通员工','管理员','超级管理员'].map(role=>`<button class="btn" onclick="switchDemoRole('${role}')">以${role}体验</button>`).join('')}</div><a href="../index.html#digital">返回作品集</a></main>`;return}

const nav=[['broadcast','数字人播报'],['qa','二维数字人问答'],...(user.role!=='普通员工'?[['knowledge','知识库配置'],['resources','资源管理']]:[]),...(['管理员','超级管理员'].includes(user.role)?[['settings','平台管理']]:[])];let group=page.startsWith('broadcast')?'broadcast':page.startsWith('qa')?'qa':page.startsWith('knowledge')?'knowledge':page.startsWith('settings')?'settings':page; if(!nav.some(x=>x[0]===group)){page='broadcast';group='broadcast'}
$('#app').innerHTML=`<div class="shell"><aside class="side"><a class="brand" href="index.html"><img src="brand.svg?v=2" alt="澄屿数字标识"><span>澄屿数字<small>内容与数字人工作空间</small></span></a><div class="nav-caption">工作空间</div>${nav.map(([p,n])=>`<button class="${group===p?'active':''}" onclick="go('${p}')"><span class="nav-symbol" aria-hidden="true">${navIcon(p)}</span>${n}</button>`).join('')}<div class="side-bottom"><span class="demo-pill">作品集交互演示</span><button onclick="demoAbout()">演示说明</button><a href="../index.html#digital">返回作品集 <span>↗</span></a></div></aside><main class="main"><header class="top"><div class="workspace-breadcrumb"><span>工作空间</span><i>/</i><strong>${nav.find(x=>x[0]===group)?.[1]||'内容工作台'}</strong></div><div class="topright"><label class="role-switch"><span>体验角色</span><select aria-label="切换体验角色" onchange="switchDemoRole(this.value)">${['普通员工','管理员','超级管理员'].map(role=>`<option ${user.role===role?'selected':''}>${role}</option>`).join('')}</select></label><button class="btn link reset-demo" onclick="resetDemo()">重置示例</button><button class="profile-button" aria-label="账号设置" onclick="account()">访</button></div></header><div class="content" id="view"></div><div class="demo-footer">虚构品牌与示例数据 · AI、语音与视频生成为本地模拟</div></main></div>`; ({broadcast:broadcastList,'broadcast-edit':broadcastEdit,'broadcast-result':broadcastResult,qa:qaList,'qa-edit':qaEdit,'qa-settings':qaSettings,'qa-publish':qaPublish,'qa-conversations':projectConversationPage,knowledge:kbList,'knowledge-create':kbCreate,'knowledge-detail':kbDetail,resources:resources,logs:logs,members:members,settings:settings,'settings-member':memberEdit,'settings-member-new':memberNew,spaces:spaces}[page]||broadcastList)()}
