function account(){modal('账号',`<p>登录账号：${esc(user.account||user.name)}</p><label for="accountDisplayName">用户名</label><input id="accountDisplayName" type="text" value="${esc(user.name)}" maxlength="50"><p class="hint">修改用户名不会改变登录账号。</p>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveAccountName()">保存</button>`)}
function saveAccountName(){let displayName=$('#accountDisplayName').value.trim();if(!displayName){alert('请输入用户名');return}let accountName=user.account||user.name;let member=db.members.find(m=>m.id===user.memberId)||db.members.find(m=>m.username===accountName);if(member){member.displayName=displayName;user.memberId=member.id}else{db.accountProfiles=db.accountProfiles||{};db.accountProfiles[accountName]={...(db.accountProfiles[accountName]||{}),displayName}}user.account=accountName;user.name=displayName;write('user',user);record('修改用户名');closeModal();render()}

const head=(title,desc,action='')=>{const back=action.includes('page-back');return `<div class="title"><div class="title-heading">${back?action:''}<div><h1>${title}</h1><div class="muted">${desc}</div></div></div>${back?'':action}</div>`};
function statusClass(status){return ({'已完成':'done','已发布':'done','排队中':'pending','生成中':'running','失败':'failed','确认中':'pending','已下线':'offline','草稿':'draft'})[status]||'draft'}
function broadcastStatus(status){return status==='确认中'?'生成中':status}
function projectImage(item){return item.img||db.resources.find(r=>r.id===item.avatar)?.img||'avatars/avatar-01.png'}
function projectUpdatedTime(value){const text=String(value||'').trim(),m=text.match(/^(\d{4})[-/年](\d{1,2})[-/月](\d{1,2})日?(?:[\sT]+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?/);if(!m)return null;const date=new Date(Number(m[1]),Number(m[2])-1,Number(m[3]),Number(m[4]||0),Number(m[5]||0),Number(m[6]||0));return Number.isFinite(date.getTime())?date.getTime():null}
function compareProjectTimes(a,b,order){const left=projectUpdatedTime(a),right=projectUpdatedTime(b);if(left===null&&right===null)return 0;if(left===null)return 1;if(right===null)return -1;return order==='asc'?left-right:right-left}
function sortedProjects(items,order='desc'){return items.slice().sort((a,b)=>compareProjectTimes(a.updated,b.updated,order))}
function sortProjectCards(order){const grid=$('#projectGrid');if(!grid)return;const cards=Array.from(grid.querySelectorAll(':scope > .project-card'));cards.sort((a,b)=>compareProjectTimes(a.dataset.updated,b.dataset.updated,order));cards.forEach(card=>grid.appendChild(card))}
function closeOtherProjectMenus(menu){if(!menu.open)return;document.querySelectorAll('.project-menu[open]').forEach(other=>{if(other!==menu)other.open=false})}
document.addEventListener?.('click',event=>{if(!event.target.closest('.project-menu'))document.querySelectorAll('.project-menu[open]').forEach(menu=>menu.open=false)});
let broadcastBatchMode=false;const broadcastSelected=new Set();
function broadcastList(){
 $('#view').innerHTML=head('数字人播报','创建播报项目，管理草稿和生成结果',`<button class="btn primary" onclick="newProject()">＋ 新建播报</button>`)+`<div class="history-tools"><div class="toolbar"><input id="search" placeholder="搜索项目名称" oninput="filterRows()"><select id="filter" onchange="filterRows()" style="width:150px"><option value="">全部状态</option>${['草稿','排队中','生成中','已完成','失败'].map(x=>`<option>${x}</option>`).join('')}</select><select id="timeSort" aria-label="按更新时间排序" onchange="sortProjectCards(this.value)" style="width:160px"><option value="desc">时间：从新到旧</option><option value="asc">时间：从旧到新</option></select>${broadcastBatchMode?`<button class="btn" onclick="selectVisibleBroadcasts()">全选当前结果</button><button class="btn danger" id="broadcastBatchDelete" onclick="deleteSelectedBroadcasts()">删除所选（${broadcastSelected.size}）</button><button class="btn" onclick="toggleBroadcastBatch()">取消</button>`:`<button class="btn" onclick="toggleBroadcastBatch()">批量删除</button>`}</div></div><div class="project-grid broadcast-grid" id="projectGrid">${sortedProjects(db.projects).map(p=>`<article class="project-card broadcast-project-card ${broadcastBatchMode?'broadcast-select-mode':''}" data-project-id="${esc(p.id)}" data-name="${esc(p.name.toLowerCase())}" data-status="${esc(broadcastStatus(p.status))}" data-updated="${esc(p.updated||'')}"><div class="project-media broadcast-media">${broadcastBatchMode?`<label class="qa-select-label"><input type="checkbox" aria-label="选择${esc(p.name)}" ${broadcastSelected.has(p.id)?'checked':''} onchange="setBroadcastSelection(this)"></label>`:''}<img src="${esc(projectImage(p))}" alt=""><span class="project-status ${statusClass(broadcastStatus(p.status))}">${esc(broadcastStatus(p.status))}</span>${p.duration&&p.duration!=='-'?`<span class="project-duration">${esc(p.duration)}</span>`:''}<details class="project-menu" ontoggle="closeOtherProjectMenus(this)"><summary aria-label="项目操作">···</summary><div class="project-menu-list">${['草稿','排队中','已完成'].includes(p.status)?`<button class="project-action" onclick="copyProject('${p.id}')">复制</button>`:''}<button class="project-action" onclick="delProject('${p.id}')">删除</button></div></details></div><div class="project-info"><div class="project-title">${esc(p.name)}</div><div class="project-date">${esc(p.updated||'')}</div>${!broadcastBatchMode&&['草稿','失败','已完成','生成中'].includes(broadcastStatus(p.status))?`<button class="btn primary broadcast-card-main" onclick="${broadcastStatus(p.status)==='生成中'?`viewBroadcastSettings('${p.id}')`:`editProject('${p.id}')`}">${broadcastStatus(p.status)==='生成中'?'查看设置':p.status==='已完成'?'查看结果':'继续编辑'}</button>`:''}</div></article>`).join('')}</div>${db.projects.length?'':'<div class="empty">暂无播报项目，点击“新建播报”开始</div>'}`;
}
function toggleBroadcastBatch(){broadcastBatchMode=!broadcastBatchMode;broadcastSelected.clear();broadcastList()}
function setBroadcastSelection(input){const card=input.closest('[data-project-id]');if(!card)return;if(input.checked)broadcastSelected.add(card.dataset.projectId);else broadcastSelected.delete(card.dataset.projectId);const button=$('#broadcastBatchDelete');if(button)button.textContent=`删除所选（${broadcastSelected.size}）`}
function selectVisibleBroadcasts(){document.querySelectorAll('.broadcast-project-card:not([hidden]) .qa-select-label input').forEach(input=>{input.checked=true;const card=input.closest('[data-project-id]');if(card)broadcastSelected.add(card.dataset.projectId)});const button=$('#broadcastBatchDelete');if(button)button.textContent=`删除所选（${broadcastSelected.size}）`}
async function deleteSelectedBroadcasts(){const projects=db.projects.filter(p=>broadcastSelected.has(p.id)&&!pendingBroadcastDeletions.has(p.id));if(!projects.length){alert('请选择要删除的项目');return}const processing=projects.filter(p=>['排队中','生成中','确认中'].includes(p.status));if(!confirm(`确定删除所选 ${projects.length} 个播报项目？${processing.length?`其中 ${processing.length} 个任务将先取消，确认取消后删除。`:''}删除后无法恢复。`))return;const removed=[],failed=[];for(const p of projects){if(['排队中','生成中','确认中'].includes(p.status)){pendingBroadcastDeletions.add(p.id);const expected=p.status;try{const result=await cancelBroadcastTaskForPrototype(p);const latest=db.projects.find(x=>x.id===p.id);if(!result?.confirmed||!latest||latest.status!==expected){failed.push(p.name);continue}}catch(e){failed.push(p.name);continue}finally{pendingBroadcastDeletions.delete(p.id)}}removed.push(p.id)}if(removed.length){const ids=new Set(removed);db.projects=db.projects.filter(p=>!ids.has(p.id));record(`批量删除播报项目（${removed.length} 个）`)}broadcastBatchMode=false;broadcastSelected.clear();render();if(failed.length)alert(`以下任务取消未确认，未删除：${failed.join('、')}`)}
function filterRows(){let q=$('#search')?.value.toLowerCase()||'',s=$('#filter')?.value||'';document.querySelectorAll('[data-name][data-status]').forEach(e=>e.hidden=!e.dataset.name.includes(q)||(s&&e.dataset.status!==s))}
let broadcastReadOnly=false;
function newProject(){broadcastReadOnly=false;current={id:id(),name:'未命名播报'+new Date().toLocaleDateString('zh-CN'),status:'草稿',text:'',speed:'1',ratio:'16:9'};go('broadcast-edit')}function editProject(i){broadcastReadOnly=false;let p=db.projects.find(x=>x.id===i);if(!p||!['草稿','失败','已完成'].includes(p.status))return;current=structuredClone(p);go(current.status==='已完成'?'broadcast-result':'broadcast-edit')}function viewBroadcastSettings(i){const p=db.projects.find(x=>x.id===i);if(!p||broadcastStatus(p.status)!=='生成中')return;broadcastReadOnly=true;current=structuredClone(p);go('broadcast-edit')}function copyProject(i){let source=db.projects.find(x=>x.id===i);if(!source||!['草稿','排队中','已完成'].includes(source.status))return;let p=structuredClone(source);p.id=id();p.name+=' - 副本';p.status='草稿';p.updated=now();db.projects.unshift(p);record('复制播报项目');render()}const pendingBroadcastDeletions=new Set();
// 原型使用本地模拟取消确认；接入真实任务服务时必须以服务端确认结果为准。
async function cancelBroadcastTaskForPrototype(project){return {confirmed:!!project}}
async function delProject(i){let p=db.projects.find(x=>x.id===i);if(!p||pendingBroadcastDeletions.has(i))return;const processing=['排队中','生成中','确认中'].includes(p.status);if(processing){if(!confirm('该任务正在处理。确认取消任务，并在取消成功后删除？'))return;pendingBroadcastDeletions.add(i);let expectedStatus=p.status;try{const result=await cancelBroadcastTaskForPrototype(p);let latest=db.projects.find(x=>x.id===i);if(!result?.confirmed||!latest||latest.status!==expectedStatus){alert('任务取消尚未确认，未删除项目。');return}db.projects=db.projects.filter(x=>x.id!==i);record('取消并删除播报任务');render()}catch(e){alert('任务取消失败，未删除项目。')}finally{pendingBroadcastDeletions.delete(i)}return}if(confirm('确定删除该项目的草稿和成片吗？')){db.projects=db.projects.filter(x=>x.id!==i);record('删除播报项目');render()}}

function updateAvatarPreview(value){const img=db.resources.find(r=>r.id===value)?.img;const preview=$('#avatarPreview');if(preview&&img)preview.src=img}
function updateBroadcastPreview(){const avatar=$('#avatarPreview'),canvas=$('#broadcastPreview');if(!avatar||!canvas)return;const avatarResource=db.resources.find(r=>r.id===$('#avatar')?.value&&r.type==='形象');const background=db.resources.find(r=>r.id===$('#bg')?.value&&r.type==='背景');avatar.src=avatarResource?.img||'avatars/avatar-01.png';canvas.style.backgroundImage=background?.img?'url('+JSON.stringify(background.img)+')':'none';canvas.classList.toggle('is-portrait',$('#ratio')?.value==='9:16')}
let broadcastAssetTab='形象',broadcastAudioState='idle',broadcastAudioJob=0;
function broadcastEdit(){broadcastAssetTab='形象';broadcastAudioState='idle';broadcastAudioJob++;$('#view').innerHTML=head(broadcastReadOnly?'查看播报设置':'新建／编辑播报','单人、单场景播报',`<button class="page-back" type="button" onclick="if(broadcastReadOnly||confirm('离开前请确认已保存草稿，继续离开？'))go('broadcast')"><span aria-hidden="true">‹</span> 返回项目</button>`)+`<div class="broadcast-workspace"><aside class="panel broadcast-assets"><h3>素材选择</h3><div class="broadcast-asset-tabs" role="group" aria-label="素材分类">${['形象','音色','背景'].map(type=>`<button type="button" data-asset-tab="${type}" onclick="switchBroadcastAssets('${type}')">${type}</button>`).join('')}</div><div id="broadcastAssetList" class="broadcast-asset-list"></div></aside><section class="panel broadcast-center"><div class="broadcast-center-head"><h3>画面预览</h3><span class="hint">单人播报</span></div><div class="broadcast-preview-area"><div class="preview broadcast-preview" id="broadcastPreview"><img id="avatarPreview" src="${esc(db.resources.find(r=>r.id===current.avatar)?.img||'avatars/avatar-01.png')}" alt="形象构图示意"></div></div><div class="broadcast-audio"><div><strong>音频生成</strong><p class="hint">选择音色并填写播报文案</p></div><div class="broadcast-audio-fields"><div><label for="voice">音色 <span class="required-star">*</span></label><select id="voice" onchange="invalidateBroadcastAudio();renderBroadcastAssets()">${selection('音色',current.voice)}</select></div><div><label for="speed">语速 <span class="required-star">*</span></label><select id="speed" onchange="invalidateBroadcastAudio()">${['0.8','0.9','1','1.1','1.2'].map(x=>`<option ${x===current.speed?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="broadcast-audio-actions"><button class="btn primary" id="audioGenerate" type="button" onclick="generateBroadcastAudio()">生成音频</button><button class="btn" id="audioListen" type="button" onclick="listenBroadcastAudio()" disabled>▶ 试听</button><button class="btn" id="audioRegenerate" type="button" onclick="generateBroadcastAudio()" disabled>重新生成</button></div></div></section><section class="panel broadcast-settings"><h3>播报设置</h3><label>项目名称 <span class="required-star">*</span></label><input id="pname" type="text" value="${esc(current.name)}"><label>播报文案 <span class="required-star">*</span></label><textarea id="ptext" maxlength="5000" oninput="$('#count').textContent=this.value.length+' 字';invalidateBroadcastAudio()">${esc(current.text||'')}</textarea><div class="bar"><span class="hint" id="count">${(current.text||'').length} 字</span><button class="btn link" onclick="$('#ptext').value='';$('#count').textContent='0 字';invalidateBroadcastAudio()">清空</button></div><p class="hint">建议不超过 1000 字、预计成片不超过 5 分钟；实际限制以引擎为准。</p><div class="broadcast-output-fields"><div><label for="resolution">分辨率 <span class="required-star">*</span></label><select id="resolution">${['720p','1080p'].map(value=>`<option value="${value}" ${(current.resolution||'720p')===value?'selected':''}>${value}</option>`).join('')}</select></div><div><label for="videoFormat">视频格式 <span class="required-star">*</span></label><select id="videoFormat">${['MP4','MOV'].map(value=>`<option value="${value}" ${(current.format||'MP4')===value?'selected':''}>${value}</option>`).join('')}</select></div></div><input id="avatar" type="hidden" value="${esc(current.avatar||'')}"><input id="bg" type="hidden" value="${esc(current.bg||'')}"><label>画面比例 <span class="required-star">*</span></label><select id="ratio" onchange="updateBroadcastPreview()"><option ${current.ratio==='16:9'?'selected':''}>16:9</option><option ${current.ratio==='9:16'?'selected':''}>9:16</option></select><div class="broadcast-settings-actions"><button class="btn" onclick="saveProject(false)">保存草稿</button><button class="btn primary" onclick="saveProject(true)">生成播报视频</button></div></section></div>`;updateBroadcastPreview();renderBroadcastAssets();if(broadcastReadOnly){document.querySelectorAll('.broadcast-workspace input,.broadcast-workspace textarea,.broadcast-workspace select,.broadcast-workspace button').forEach(el=>el.disabled=true)}}
function switchBroadcastAssets(type){broadcastAssetTab=type;renderBroadcastAssets()}
function renderBroadcastAssets(){const list=$('#broadcastAssetList');if(!list)return;const selectId={形象:'avatar',音色:'voice',背景:'bg'}[broadcastAssetTab],selected=$('#'+selectId)?.value||'';document.querySelectorAll('[data-asset-tab]').forEach(btn=>{const active=btn.dataset.assetTab===broadcastAssetTab;btn.classList.toggle('active',active);btn.setAttribute('aria-pressed',String(active))});const assets=db.resources.filter(r=>r.type===broadcastAssetTab&&r.status==='可用');list.innerHTML=assets.map(r=>`<button type="button" class="broadcast-asset-card ${r.id===selected?'selected':''}" aria-pressed="${r.id===selected}" onclick="chooseBroadcastAsset('${selectId}','${encodeURIComponent(r.id)}')">${r.img?`<span class="broadcast-asset-image"><img src="${esc(r.img)}" alt=""></span>`:'<span class="broadcast-asset-voice" aria-hidden="true">♫</span>'}<span class="broadcast-asset-name">${esc(r.name)}</span></button>`).join('')||'<div class="hint">暂无可用素材</div>'}
function chooseBroadcastAsset(selectId,encodedId){let select=$('#'+selectId);if(!select)return;let next=decodeURIComponent(encodedId),changed=select.value!==next;select.value=next;if(selectId==='voice'&&changed)invalidateBroadcastAudio();updateBroadcastPreview();renderBroadcastAssets()}
function updateBroadcastAudioControls(){const generate=$('#audioGenerate'),listen=$('#audioListen'),regenerate=$('#audioRegenerate');if(!generate||!listen||!regenerate)return;const working=broadcastAudioState==='generating',ready=broadcastAudioState==='ready';generate.disabled=working;listen.disabled=!ready;regenerate.disabled=!ready}
function invalidateBroadcastAudio(){if(broadcastAudioState==='idle')return;broadcastAudioJob++;broadcastAudioState='idle';updateBroadcastAudioControls();const message=$('#broadcastAudioModalMessage');if(message)message.textContent='播报文案或声音设置已更改，请重新生成。';const spinner=$('#broadcastAudioSpinner');if(spinner)spinner.hidden=true;const footer=$('#broadcastAudioModalFooter');if(footer)footer.hidden=false}
function generateBroadcastAudio(){if(broadcastAudioState==='generating')return;if(!$('#ptext').value.trim()){alert('请先填写播报文案');return}if(!$('#voice').value){alert('请先选择音色');return}broadcastAudioState='generating';const job=++broadcastAudioJob,projectId=current?.id;updateBroadcastAudioControls();modal('音频生成',`<div class="broadcast-audio-modal"><div class="broadcast-audio-spinner" id="broadcastAudioSpinner" aria-hidden="true"></div><p id="broadcastAudioModalMessage" role="status">正在模拟音频生成，请稍候…</p></div>`,`<span id="broadcastAudioModalFooter" hidden><button class="btn primary" onclick="closeModal()">完成</button></span>`);setTimeout(()=>{if(job!==broadcastAudioJob||page!=='broadcast-edit'||current?.id!==projectId)return;broadcastAudioState='ready';updateBroadcastAudioControls();const message=$('#broadcastAudioModalMessage');if(message)message.textContent='音频配置完成（演示）';const spinner=$('#broadcastAudioSpinner');if(spinner)spinner.hidden=true;const footer=$('#broadcastAudioModalFooter');if(footer)footer.hidden=false},3000)}
function listenBroadcastAudio(){if(broadcastAudioState!=='ready')return;alert('音频暂无法播放。')}


function saveProject(generate){if(broadcastReadOnly)return;Object.assign(current,{name:$('#pname').value.trim()||current.name,text:$('#ptext').value,voice:$('#voice').value,avatar:$('#avatar').value,bg:$('#bg').value,speed:$('#speed').value,resolution:$('#resolution').value,format:$('#videoFormat').value,ratio:$('#ratio').value,updated:now()});if(generate&&(!current.text||!current.voice||!current.avatar||!current.bg)){alert('请填写文案并选择形象、音色和背景');return}if(generate&&current.text.length>1000){alert('文案超过建议上限，请拆分；文案已保留');return}current.status=generate?'排队中':'草稿';let i=db.projects.findIndex(x=>x.id===current.id);if(i<0)db.projects.unshift(current);else db.projects[i]=current;record(generate?'提交播报生成':'保存播报草稿');if(generate){simulateBroadcast(current.id);alert('演示任务已接收，稍后可查看完成状态')}go('broadcast')}
function broadcastResult(){$('#view').innerHTML=head(esc(current.name),'播报结果',`<button class="page-back" type="button" onclick="go('broadcast')"><span aria-hidden="true">‹</span> 返回列表</button>`)+`<div class="grid"><div class="panel"><div class="preview">演示预览，不生成真实视频</div></div><div class="panel"><h3>生成配置</h3><p>文案：${esc(current.text)}</p><p>形象：${esc(db.resources.find(r=>r.id===current.avatar)?.name||'—')}</p><p>音色：${esc(db.resources.find(r=>r.id===current.voice)?.name||'—')}</p><p>背景：${esc(db.resources.find(r=>r.id===current.bg)?.name||'—')}</p><p>画面比例：${esc(current.ratio)}</p><p>语速：${esc(current.speed)} 倍</p><p>分辨率：${esc(current.resolution||'720p')}</p><p>文件格式：${esc(current.format||'MP4')}</p><button class="btn" onclick="go('broadcast-edit')">修改配置并重新生成</button> <button class="btn" onclick="alert('暂无法下载')">下载视频</button></div></div>`}
