function deleteQaApps(ids){const targets=db.apps.filter(a=>ids.includes(a.id));if(!targets.length){alert('请选择要删除的项目');return}if(targets.some(a=>!['草稿','已下线'].includes(a.status))){alert('已发布的问答不能删除，请先下架。');return}if(!confirm(`确定删除所选 ${targets.length} 个问答项目？删除后无法恢复。`))return;const removed=new Set(targets.map(a=>a.id));db.apps=db.apps.filter(a=>!removed.has(a.id));record('删除问答应用：'+targets.map(a=>a.name).join('、'));qaSelected.clear();qaBatchMode=false;render()}
